      "{\"description\":\"A part of the \\\"Millennial Movement\\\" that wanders amidst the winds. Increases Elemental Mastery by 75. When the Elemental Skills or Elemental Bursts of the character wielding this weapon hit opponents, that character gains a Sigil of Remembrance. This effect can be triggered once every 0.2s and can be triggered even if said character is not on the field. When you possess 4 Sigils of Remembrance, all of them will be consumed and all nearby party members will obtain the \\\"Millennial Movement: Farewell Song\\\" effect for 12s. \\\"Millennial Movement: Farewell Song\\\" increases Elemental Mastery by 125 and increases ATK by 25%. Once this effect is triggered, you will not gain Sigils of Remembrance for 20s. Of the many effects of the \\\"Millennial Movement,\\\" buffs of the same type will not stack.\",\"values\":[\"75\",\"125\",\"25%\"]}",
      "{\"description\":\"A part of the \\\"Millennial Movement\\\" that wanders amidst the winds. Increases Elemental Mastery by 90. When the Elemental Skills or Elemental Bursts of the character wielding this weapon hit opponents, that character gains a Sigil of Remembrance. This effect can be triggered once every 0.2s and can be triggered even if said character is not on the field. When you possess 4 Sigils of Remembrance, all of them will be consumed and all nearby party members will obtain the \\\"Millennial Movement: Farewell Song\\\" effect for 12s. \\\"Millennial Movement: Farewell Song\\\" increases Elemental Mastery by 150 and increases ATK by 30%. Once this effect is triggered, you will not gain Sigils of Remembrance for 20s. Of the many effects of the \\\"Millennial Movement,\\\" buffs of the same type will not stack.\",\"values\":[\"90\",\"150\",\"30%\"]}",
      "{\"description\":\"A part of the \\\"Millennial Movement\\\" that wanders amidst the winds. Increases Elemental Mastery by 105. When the Elemental Skills or Elemental Bursts of the character wielding this weapon hit opponents, that character gains a Sigil of Remembrance. This effect can be triggered once every 0.2s and can be triggered even if said character is not on the field. When you possess 4 Sigils of Remembrance, all of them will be consumed and all nearby party members will obtain the \\\"Millennial Movement: Farewell Song\\\" effect for 12s. \\\"Millennial Movement: Farewell Song\\\" increases Elemental Mastery by 175 and increases ATK by 35%. Once this effect is triggered, you will not gain Sigils of Remembrance for 20s. Of the many effects of the \\\"Millennial Movement,\\\" buffs of the same type will not stack.\",\"values\":[\"105\",\"175\",\"35%\"]}",
      "{\"description\":\"A part of the \\\"Millennial Movement\\\" that wanders amidst the winds. Increases Elemental Mastery by 120. When the Elemental Skills or Elemental Bursts of the character wielding this weapon hit opponents, that character gains a Sigil of Remembrance. This effect can be triggered once every 0.2s and can be triggered even if said character is not on the field. When you possess 4 Sigils of Remembrance, all of them will be consumed and all nearby party members will obtain the \\\"Millennial Movement: Farewell Song\\\" effect for 12s. \\\"Millennial Movement: Farewell Song\\\" increases Elemental Mastery by 200 and increases ATK by 40%. Once this effect is triggered, you will not gain Sigils of Remembrance for 20s. Of the many effects of the \\\"Millennial Movement,\\\" buffs of the same type will not stack.\",\"values\":[\"120\",\"200\",\"40%\"]}"
