      "{\"description\":\"When the Traveler equips this, their ATK will increase by 16% for 8s after they hit an opponent. At the same time, they will also regenerate 3 Elemental Energy. This effect can trigger once every 5s. This can be triggered even when the character is not on the field.\",\"values\":[\"16%\",\"8\",\"3\",\"5\"]}",
