      "{\"description\":\"A part of the \\\"Millennial Movement\\\" that wanders amidst the winds. Increases DMG by 15%. When the character wielding this weapon triggers Elemental Reactions, they gain a Sigil of Rebellion. This effect can be triggered once every 0.5s and can be triggered even if said character is not on the field. When you possess 2 Sigils of Rebellion, all of them will be consumed and all nearby party members will obtain \\\"Millennial Movement: Song of Resistance\\\" for 12s. \\\"Millennial Movement: Song of Resistance\\\" increases Normal, Charged and Plunging Attack DMG by 24% and increases ATK by 30%. Once this effect is triggered, you will not gain Sigils of Rebellion for 20s. Of the many effects of the \\\"Millennial Movement,\\\" buffs of the same type will not stack.\",\"values\":[\"15%\",\"24%\",\"30%\"]}",
      "{\"description\":\"A part of the \\\"Millennial Movement\\\" that wanders amidst the winds. Increases DMG by 17.5%. When the character wielding this weapon triggers Elemental Reactions, they gain a Sigil of Rebellion. This effect can be triggered once every 0.5s and can be triggered even if said character is not on the field. When you possess 2 Sigils of Rebellion, all of them will be consumed and all nearby party members will obtain \\\"Millennial Movement: Song of Resistance\\\" for 12s. \\\"Millennial Movement: Song of Resistance\\\" increases Normal, Charged and Plunging Attack DMG by 28% and increases ATK by 35%. Once this effect is triggered, you will not gain Sigils of Rebellion for 20s. Of the many effects of the \\\"Millennial Movement,\\\" buffs of the same type will not stack.\",\"values\":[\"17.5%\",\"28%\",\"35%\"]}",
      "{\"description\":\"A part of the \\\"Millennial Movement\\\" that wanders amidst the winds. Increases DMG by 20%. When the character wielding this weapon triggers Elemental Reactions, they gain a Sigil of Rebellion. This effect can be triggered once every 0.5s and can be triggered even if said character is not on the field. When you possess 2 Sigils of Rebellion, all of them will be consumed and all nearby party members will obtain \\\"Millennial Movement: Song of Resistance\\\" for 12s. \\\"Millennial Movement: Song of Resistance\\\" increases Normal, Charged and Plunging Attack DMG by 32% and increases ATK by 40%. Once this effect is triggered, you will not gain Sigils of Rebellion for 20s. Of the many effects of the \\\"Millennial Movement,\\\" buffs of the same type will not stack.\",\"values\":[\"20%\",\"32%\",\"40%\"]}"
